fn sqlite_snapshot_equation_deep_erased_native_retains_flat_owned_state_on_small_stack(){
 let(f,value)=fixture();let depth=f["deep"].as_u64().unwrap()as usize;
 std::thread::Builder::new().stack_size(256*1024).spawn(move||{
  let mut value=value;let mut node=EquationNode{label:EquationNodeLabel(u64::MAX),kind:EquationNodeKind::Symbol{name:"leaf\0世界".into()}};for _ in 0..depth{node=EquationNode{label:EquationNodeLabel(u64::MAX),kind:EquationNodeKind::Mul{factors:vec![node]}}}EquationSnapshot::retire_sqlite_snapshot(EquationSnapshot{graph:value.graph.clone(),geometry:value.geometry.clone(),notation:value.notation.clone(),results:value.results.clone(),computed:value.computed.clone(),equation:EquationExprSnapshot{expr:std::mem::replace(&mut value.equation.expr,node),next_label:0}});
  let limits=SqliteDatabaseLimits::default();let expected=value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let provider=crate::standards::v1::subsets::any::io::io().native.codec.snapshot_sqlite.unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.mathematical.equation".into(),standard:"1".into(),subset:"*".into()};
  for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=(provider.import)(crate::MATH_DOCUMENT_SCHEMA,&dialect,expected.clone(),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;assert_eq!((provider.export)(crate::MATH_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value,expected);}
  EquationSnapshot::retire_sqlite_snapshot(value);
 }).unwrap().join().unwrap();
}

#[test]
fn sqlite_snapshot_equation_controlled_typed_construction_preserves_admission_and_known_work(){
 let(f,value)=fixture();let text=store::ArtifactDsl::print_dsl(&value);let(_,body)=store::semio_format::split_text_preamble(&text).unwrap();let spec=<EquationSnapshot as store::ArtifactPack>::record_spec().unwrap();let record=semio_framework_dsl_record::parse_exact(body,&spec,&semio_framework_dsl_record::ParseOptions{limits:semio_framework_diagnostic::Limits::default(),mode:semio_framework_dsl_record::SourceMode::Document}).unwrap();let bind=crate::standards::v1::subsets::any::io::binary::snapshot::reconstruct_pack_record_controlled;
 let mut callback=|_:semio_framework_value::native_decoding::NativeDecodeProgress|true;let mut control=semio_framework_value::NativeDecodeControl::new(1024*1024,&mut callback);let restored=bind(&record,&mut control,1_000_000).unwrap();assert_eq!(restored,value);EquationSnapshot::retire_sqlite_snapshot(restored);
 let mut control=semio_framework_value::NativeDecodeControl::new(1024*1024,&mut callback);assert!(bind(&record,&mut control,f["maxRows"].as_u64().unwrap()as usize).is_err());assert_eq!(control.owned_bytes(),0,"row admission must precede typed field copying");
 let mut control=semio_framework_value::NativeDecodeControl::new(f["maxValueBytes"].as_u64().unwrap()as usize,&mut callback);assert!(bind(&record,&mut control,1_000_000).is_err());
 EquationSnapshot::retire_sqlite_snapshot(value);
}

