fn sqlite_snapshot_equation_whole_native_control_preserves_typed_fields_and_interior_cancellation(){let(_,mut value)=fixture();let mut node=EquationNode{label:EquationNodeLabel(u64::MAX),kind:EquationNodeKind::Integer{lexeme:"noncanonical arbitrary String 世界".repeat(4096)}};for _ in 0..600{node=EquationNode{label:EquationNodeLabel(u64::MAX),kind:EquationNodeKind::Add{terms:vec![node]}}}let old=std::mem::replace(&mut value.equation.expr,node);let retired=EquationSnapshot{graph:value.graph.clone(),geometry:value.geometry.clone(),notation:value.notation.clone(),results:value.results.clone(),computed:value.computed.clone(),equation:EquationExprSnapshot{expr:old,next_label:0}};EquationSnapshot::retire_sqlite_snapshot(retired);let limits=SqliteDatabaseLimits::default();let expected=value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();for payload in[store::os_io::IoPayload::Text(store::ArtifactDsl::print_dsl(&value)),store::os_io::IoPayload::Binary(store::ArtifactPack::encode_pack(&value))]{let restored=EquationSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),expected);EquationSnapshot::retire_sqlite_snapshot(restored);for limits in[SqliteDatabaseLimits{max_rows:10,..limits},SqliteDatabaseLimits{max_allocation_bytes:4096,..limits}]{assert!(EquationSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}let mut interior=false;let mut progress=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==SqliteSnapshotPhase::DecodeNative&&event.completed>=256&&event.completed<event.total{interior=true;false}else{true}};assert!(EquationSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut progress,limits)).is_err());assert!(interior);}EquationSnapshot::retire_sqlite_snapshot(value);}
