fn sqlite_snapshot_equation_explicit_native_output_exact_file_frontier_and_unicode_cancel() {
 let (_,mut snapshot)=fixture();snapshot.equation.expr.kind=crate::standards::v1::subsets::any::io::sqlite::snapshot::EquationNodeKind::Symbol{name:"interior 世界".repeat(20000)};
 let limits=SqliteDatabaseLimits::default();
 for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text] {
  let payload=<EquationSnapshot as ArtifactSqliteSnapshot>::encode_sqlite_snapshot_native(&snapshot,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();
  let length=match &payload{store::os_io::IoPayload::Binary(bytes)=>bytes.len(),store::os_io::IoPayload::Text(text)=>text.len()};
  assert!(<EquationSnapshot as ArtifactSqliteSnapshot>::encode_sqlite_snapshot_native(&snapshot,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:length,..limits})).is_ok());
  assert!(<EquationSnapshot as ArtifactSqliteSnapshot>::encode_sqlite_snapshot_native(&snapshot,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:length-1,..limits})).is_err());
  let mut interior=false;
  assert!(<EquationSnapshot as ArtifactSqliteSnapshot>::encode_sqlite_snapshot_native(&snapshot,encoding,&mut SqliteSnapshotControl::new(&mut |p|{if p.phase==store::sqlite_snapshot::SqliteSnapshotPhase::EncodeNative&&p.completed>=256&&p.completed<p.total{interior=true;false}else{true}},limits)).is_err());
  assert!(interior);
 }
 <EquationSnapshot as ArtifactSqliteSnapshot>::retire_sqlite_snapshot(snapshot);
}
#[test]
fn sqlite_snapshot_equation_independent_consistent_surrogate_renumbering() {
 use std::{io::Write,process::{Command,Stdio}};
 let (corpus,snapshot)=fixture();let limits=SqliteDatabaseLimits::default();
 let expected=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();
 let bytes=export_sqlite_database(&expected,limits,&mut |_|true).unwrap();
 let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));const offset=Number(process.argv[1]);d.exec('PRAGMA foreign_keys=OFF');for(const{name}of d.query("SELECT name FROM sqlite_schema WHERE type='table'").all()){const identity=d.query('PRAGMA table_info('+name+')').all().find(c=>c.pk===1).name;const links=d.query('PRAGMA foreign_key_list('+name+')').all();const fields=[identity+'='+identity+'+'+offset,...links.filter(c=>c.from!==identity).map(c=>c.from+'='+c.from+'+'+offset)];d.exec('UPDATE '+name+' SET '+fields.join(','));}if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('independent renumber integrity');await Bun.write(Bun.stdout,d.serialize());d.close();"#;
 let mut child=Command::new("bun").args(["-e",script]).arg(corpus["renumberOffset"].as_u64().unwrap().to_string()).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));
 let edited=import_sqlite_database(&output.stdout,limits,&mut |_|true).unwrap();
 let restored=EquationSnapshot::from_sqlite_database(&edited,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();
 assert_eq!(restored.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),expected);
 EquationSnapshot::retire_sqlite_snapshot(restored);EquationSnapshot::retire_sqlite_snapshot(snapshot);
}
